  // target 은 체험 모드 말풍선이 가리킬 요소 id(페이지별). tour 는 그 말풍선의 제목·한 줄 설명이다(설계 2026-09-25 §3.4).
  steps: [
    // Task 17(B8, 2026-10-23): RP 운영자가 IdP 에서 RP 를 만드는 단계 — 승인(approve) 앞에 새로 끼운다. 체험 모드
    // 조건(condMet)은 그대로이므로 완료 판정은 demo.js 의 evaluate() 가 'approve' 와 같은 신호(rp_approved)로 겸해 본다
    // (승인된 RP 가 있으면 그 전에 반드시 만들어졌다).
    { key: 'rp_create', where: ['idp_rp'], target: { idp_rp: 'rpCreateBtn' }, ko: { title: 'RP 만들기', hint: 'RP 운영자가 IdP 에서 RP 계정을 만들고 서버를 띄웁니다.' }, en: { title: 'Create an RP', hint: 'The RP operator creates an RP at the IdP and starts the server.' },
      tour: { ko: { title: '1. RP 를 만드세요', body: 'RP 운영자 계정으로 로그인해 "새 RP 만들기" 를 누르면 키와 실행 명령이 나옵니다. 그 명령으로 RP 서버를 띄우면 등록 요청이 IdP 로 갑니다.' }, en: { title: '1. Create an RP', body: 'Log in with an operator account and press "Create a new RP" to get a key and a run command. Starting the RP server with that command sends its registration to the IdP.' } } },
    { key: 'approve', where: ['admin'], target: { admin: 'rpsBtn' }, ko: { title: 'RP 승인', hint: 'IdP 운영자가 RP 등록을 승인합니다.' }, en: { title: 'Approve RP', hint: 'The IdP operator approves the RP registration.' },
      tour: { ko: { title: '2. RP 를 승인하세요', body: '대기 중인 RP 목록을 불러와 승인하면 그 RP 가 로그인을 받을 수 있습니다.' }, en: { title: '2. Approve the RP', body: 'Load the pending RP list and approve it so the RP can accept logins.' } } },
    // Task 17(B8): 등록은 이제 IdP 사용자 페이지(/user)에서 가입·로그인한 뒤 지갑 팝업으로 커밋먼트를 올린다
    // (cia_user.html #registerBtn) — Task 12 가 만든 흐름. wallet.html 의 옛 registerBtn(file 모드)은 그대로 있지만
    // 이 단계의 대상은 아니다.
    { key: 'register', where: ['idp_user'], target: { idp_user: 'registerBtn' }, ko: { title: '속성 커밋먼트 등록', hint: '사용자가 자기 속성의 커밋먼트와 공개키를 IdP 에 등록하고 자격증명을 받습니다(속성 값은 지갑에만 남습니다).' }, en: { title: 'Register an attribute commitment', hint: 'The user registers a commitment to their attributes and a public key with the IdP and receives a credential (the attribute values stay in the wallet).' },
      tour: { ko: { title: '3. 가입하고 커밋먼트를 등록하세요', body: 'IdP 사용자 페이지에서 비밀번호로 가입·로그인한 뒤 "지갑으로 커밋먼트 등록" 을 누르세요. 지갑 팝업이 비밀을 만들고 커밋먼트와 공개키만 IdP 에 등록합니다 — 속성은 지갑에만 남습니다.' }, en: { title: '3. Sign up and register a commitment', body: 'Sign up and log in with a password on the IdP user page, then press "Register a commitment with the wallet". The wallet popup creates the secrets and registers only the commitment and public key with the IdP — attributes stay in the wallet.' } } },
    { key: 'login', where: ['rp'], target: { rp: 'loginBtn' }, ko: { title: '로그인', hint: 'RP 전용 주소로 로그인합니다.' }, en: { title: 'Log in', hint: 'Log in with an RP-specific address.' },
      tour: { ko: { title: '4. RP 에 로그인하세요', body: '이 RP 에서만 쓰는 주소로 로그인합니다. IdP 는 어느 RP 인지 알지 못합니다.' }, en: { title: '4. Log in to the RP', body: 'Log in with an address used only at this RP. The IdP never learns which RP it is.' } } },
    // U6(2026-10-14) — 두 번째 RP 로그인(unlinkability 시연). target.rp 는 'loginBtn' 으로 login 과 같지만, 체험 모드가
    // demo.js 쪽에서 "지금 이 RP 가 두 번째 RP 인지"를 따로 봐 두 번째 RP 에서만 말풍선을 붙인다(첫 RP 는 "다른 창에서" 카드).
    { key: 'login2', where: ['rp'], target: { rp: 'loginBtn' }, ko: { title: '두 번째 로그인', hint: '다른 RP 에서도 같은 지갑으로 로그인해 주소가 다름을 봅니다.' }, en: { title: 'Second login', hint: 'Log in with the same wallet at a second RP to see a different address.' },
      tour: { ko: { title: '5. 두 번째 RP 에도 로그인하세요', body: '다른 RP(zkTWO)에서 같은 지갑으로 로그인하면 주소(PPID)가 첫 RP 와 다릅니다 — 두 RP 가 공모해도 같은 사용자임을 알 수 없습니다(unlinkability). 첫 RP 의 주소와 비교해 보세요.' }, en: { title: '5. Log in to a second RP too', body: 'Log in with the same wallet at another RP (zkTWO) and the address (PPID) differs from the first RP — even if the two RPs collude, they cannot tell it is the same user (unlinkability). Compare it with the first RP’s address.' } } },
    { key: 'use', where: ['rp', 'wallet'], target: { rp: 'revalidateBtn', wallet: 'txBtn' }, ko: { title: '이용', hint: '세션을 재검증하거나 요청·트랜잭션을 보냅니다.' }, en: { title: 'Use', hint: 'Revalidate the session, make a request, or send a transaction.' },
      tour: { ko: { title: '6. 세션을 써 보세요', body: 'RP 에서 세션을 재검증하거나 요청을 보내고, 지갑에서는 평범한 트랜잭션 1건을 보냅니다(기본 대상·조건 없음 — 늘 성공합니다).' }, en: { title: '6. Use the session', body: 'Revalidate the session or send a request at the RP, or send a single plain transaction from the wallet (default target, no conditions — always succeeds).' } } },
    { key: 'disclose', where: ['wallet', 'rp'], target: { wallet: 'claimBtn', rp: 'requirePred' }, ko: { title: '공개·조건', hint: '속성 조건만 골라 공개합니다.' }, en: { title: 'Disclose', hint: 'Reveal only chosen attribute conditions.' },
      tour: { ko: { title: '7. 조건만 골라 공개하세요', body: '① 이 "Selective disclosure proof 보내기" 버튼을 누르면 받는 주소·데이터와 조건(나이·국가)이 자동으로 채워집니다. ② 그 다음 "트랜잭션 보내기" 를 누르세요 — 값 자체는 넘기지 않고 조건만 증명합니다.' }, en: { title: '7. Disclose only conditions', body: '① Press this "Send selective disclosure proof" button: the target, data and conditions (age, country) are filled in automatically. ② Then press "Send transaction" — only the conditions are proven, never the values.' } } },
    // Task 17(B8): 계정 폐기가 /account 에서 /user 로 옮겼다(/account 는 302 redirect) — revokeBtn 은 cia_user.html 에 있다.
    { key: 'revoke', where: ['wallet', 'idp_user', 'admin'], target: { wallet: 'sessionActions', idp_user: 'revokeBtn', admin: 'revokeBtn' }, ko: { title: '폐기·복구', hint: '세션 하나 또는 계정을 폐기하고 게시합니다.' }, en: { title: 'Revoke & recover', hint: 'Revoke one session or the account, then publish.' },
      tour: { ko: { title: '8. 폐기해 보세요', body: '세션 하나 또는 계정을 폐기한 뒤, 관리자가 폐기 목록을 체인에 게시하면 효력이 생깁니다.' }, en: { title: '8. Revoke something', body: 'Revoke one session or the account; it takes effect once the admin publishes the revocation list on-chain.' } } },
    { key: 'open', where: ['rp_admin', 'admin'], target: { rp_admin: 'openBtn', admin: 'openingsBtn' }, ko: { title: '승인 개봉', hint: 'RP 와 IdP 가 함께 사용자를 알아냅니다.' }, en: { title: 'Authorized opening', hint: 'RP and IdP identify the user together.' },
      tour: { ko: { title: '9. 승인 개봉을 요청하세요', body: 'RP 가 개봉을 요청하고 IdP 가 허락해야만 사용자가 밝혀집니다.' }, en: { title: '9. Request an authorized opening', body: 'The user is identified only when the RP requests an opening and the IdP allows it.' } } },
  ],
